from dataclasses import dataclass, field
from enum import Enum

class Stage(Enum):
    TODO = 'todo'
    DONE = 'done'

@dataclass
class Task:
    title: str
    stage: Stage = Stage.TODO
    completed_steps: list[str] = field(default_factory=list)

    def __post_init__(self):
        if not self.title.strip():
            raise ValueError('title is required')
        if not isinstance(self.stage, Stage):
            raise TypeError('stage must be a Stage')

row = {'title': 'Review loops', 'stage': 'done'}
first = Task(row['title'], Stage(row['stage']))
second = Task('Review classes')
first.completed_steps.append('read')
print(first.stage is Stage.DONE)
print(first.completed_steps, second.completed_steps)
try:
    Task('Bad state', 'done')
except TypeError as error:
    print(type(error).__name__)

